L10_1.m_Pos = "L"
L10_1.m_Talk_KOREA = "심야의 살인마가 저질렀던 천사 강림 의식은 그저 엉터리 의식에 불과해!"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "深夜の殺人鬼が行った天使降臨の儀式は、ただのデタラメに過ぎない！"
L10_1.m_Talk_ENG = "The angel summoning ritual committed by the Midnight Killer was just a farce!"
L10_1.m_Talk_TWN = "午夜殺人魔所進行的天使降臨儀式不過是個荒唐的儀式而已！"
L10_1.m_Talk_DEU = "The angel summoning ritual committed by the Midnight Killer was just a farce!"
L10_1.m_Talk_FRA = "The angel summoning ritual committed by the Midnight Killer was just a farce!"
L11_1 = {}
L11_1.m_CutScenKey_Talk = "OMEN_CHARADE_INTERLUDE8@6#Talk"
L11_1.m_CutScenProcessKey = 0
L11_1.m_CutScenID = 8100123
L11_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE8"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L11_1.m_Pos = "L"
L11_1.m_Talk_KOREA = "하물며 천사라는 것이 존재한다고 해도, 정말 자네가 원하는 것을 이루어 줄 수 있을까?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "仮に天使というものが存在したとして、それが本当に君の望みを叶えられるのかね？"
L11_1.m_Talk_ENG = "Even if angels were real, would they really give you what you want?"
