L15_1.m_CharScale = L16_1
L15_1.m_CharScaleTime = 0.01
L15_1.m_Talk_KOREA = "그 세피라라는 힘이 정확히 어떤 식으로 현실에 작용하는지는 모르겠지만……."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "そのセフィラという力が、具体的にどういう風に現実に作用するのかは知らないが……"
L15_1.m_Talk_ENG = "I don't know exactly how the power of Sephira affects reality..."
