L17_1[2] = L19_1
L16_1.m_CharScale = L17_1
L16_1.m_CharScaleTime = 0.01
L16_1.m_Talk_KOREA = "자네는 자네의 기억을 재구성하는 우회적인 방법으로 세계를 되돌려 놓을 수 있었어."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "君は、君の記憶を再構成するという遠回りなやり方で世界を元に戻すことに成功した。"
L16_1.m_Talk_ENG = "But you've used it to reconstruct your memories and rewind the world indirectly."
L16_1.m_Talk_TWN = "你通過重構自己的記憶，以一種迂回的方式將世界恢復了原狀。"
L16_1.m_Talk_DEU = "But you've used it to reconstruct your memories and rewind the world indirectly."
L16_1.m_Talk_FRA = "But you've used it to reconstruct your memories and rewind the world indirectly."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "OMEN_CHARADE_INTERLUDE8@11#Talk"
L17_1.m_CutScenProcessKey = 0
L17_1.m_CutScenID = 8100123
L17_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE8"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L17_1.m_Pos = "C"
L18_1 = {}
L19_1 = 0
L20_1 = -120
L18_1[1] = L19_1
L18_1[2] = L20_1
L17_1.m_CharOffSet = L18_1
L17_1.m_TrackingTime = 0.01
L18_1 = {}
L19_1 = 1.2
L20_1 = 1.2
L18_1[1] = L19_1
L18_1[2] = L20_1
L17_1.m_CharScale = L18_1
L17_1.m_CharScaleTime = 0.01
L17_1.m_Talk_KOREA = "아마도 그건 망각의 여신으로부터 미움받는 자네이기에 떠올릴 수 있는 발상이었겠지."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "おそらくそれは、忘却の女神に愛されなかった君だからこそできた発想だったのだろう。"
L17_1.m_Talk_ENG = "Maybe that's something only you, hated by the goddess of oblivion, could've come up with."
L17_1.m_Talk_TWN = "也許那是因為你是被遺忘女神所詛咒的人，才能想到這樣的主意吧。"
L17_1.m_Talk_DEU = "Maybe that's something only you, hated by the goddess of oblivion, could've come up with."
L17_1.m_Talk_FRA = "Maybe that's something only you, hated by the goddess of oblivion, could've come up with."
