L20_1 = {}
L20_1.m_CutScenKey_Talk = "OMEN_CHARADE_INTERLUDE8@12#Talk"
L20_1.m_CutScenProcessKey = 0
L20_1.m_CutScenID = 8100123
L20_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE8"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_SERIOUS"
L20_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L20_1.m_Pos = "L"
L20_1.m_Talk_KOREA = "하지만 그렇다고 해도 기억의 당사자인 자네 자신은 과거로 돌아갈 수 없었어."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "しかし、記憶の当事者である君自身が過去に戻れたわけではなかった。"
L20_1.m_Talk_ENG = "But even so, you yourself couldn't return to the past."
L20_1.m_Talk_TWN = "但即便如此，作為記憶的主人的你自己也沒能回到過去。"
L20_1.m_Talk_DEU = "But even so, you yourself couldn't return to the past."
L20_1.m_Talk_FRA = "But even so, you yourself couldn't return to the past."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "OMEN_CHARADE_INTERLUDE8@13#Talk"
L21_1.m_CutScenProcessKey = 0
L21_1.m_CutScenID = 8100123
L21_1.m_CutScenStrID = "OMEN_CHARADE_INTERLUDE8"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L21_1.m_Pos = "L"
L21_1.m_Talk_KOREA = "그 증거로 이 세계에는 자네가 두 사람 존재하게 되지 않았나?"
