L36_1.m_Talk_KOREA = "결국, 자네는 자네가 만들어낸 세계에서도 외톨이로 남게 될 거야."
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "結局、君は君自身が作り出した世界でも一人ぼっちになるんだ。"
