L37_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L37_1.m_Pos = "L"
L37_1.m_Talk_KOREA = "누구에게도 이해받지 못한 채, 누구와도 인연을 맺지 못한 채, 미지의 존재로 남을 거라고!"
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "誰からも理解されず、誰かと縁を結ぶこともできず、未知の存在としてただ残されるだけだ！"
L37_1.m_Talk_ENG = "No one will understand you. No one will be connected to you. You'll remain as an unknown to everyone!"
L37_1.m_Talk_TWN = "沒有人理解你，也沒有人與你結緣，你將永遠是個未知的存在！"
L37_1.m_Talk_DEU = "No one will understand you. No one will be connected to you. You'll remain as an unknown to everyone!"
L37_1.m_Talk_FRA = "No one will understand you. No one will be connected to you. You'll remain as an unknown to everyone!"
