L38_1.m_Crash = 30
L38_1.m_Talk_KOREA = "아이린, 자네가 바라는 세계가 진정 그런 세계인가……?"
L38_1.m_fTalkTime = 0.03
L38_1.m_Talk_JPN = "アイリーン、君が望む世界とは、真にそのような世界なのかね……？"
