L1_1.m_fTalkTime = 0.03
L1_1.m_Talk_JPN = "あなただけは、いつまでも美しく優雅な白鳥でいて欲しいから。"
L1_1.m_Talk_ENG = "I want you to always remain a beautiful, graceful swan, no matter where you are."
