L9_1 = "그런데 참 이상하죠? 당신은 지금 또다시 과거로 도망치려 하고 있네요?"
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "なのにおかしいですね？　あなたは今、またしても過去に逃げようとしている。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "But it's strange, right? You're trying to run back to the past again."
L8_1.m_Talk_ENG = L9_1
L9_1 = "不過真奇怪啊？你現在又想逃回過去了嗎？"
