L10_1 = "R"
L9_1.m_Pos = L10_1
L10_1 = "분명, 당신도 알고 있을 텐데요? 도망치는 것만으로는 아무것도 바꿀 수 없다는 것쯤은……!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "あなたもわかっているはずです。逃げるだけでは何も変えられないってことくらい……！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You know as well as I do... that running away can't change anything...!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "你肯定也知道吧？光是逃避是無法改變任何事情的！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "You know as well as I do... that running away can't change anything...!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "You know as well as I do... that running away can't change anything...!"
L9_1.m_Talk_FRA = L10_1
