L13_1.m_CharScaleTime = 0.01
L14_1 = "그렇다면 나중에 후회하지 말고, 적어도 마지막에는 솔직하게 본심을 전하라고요……!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ならば後になって後悔などせず、せめて最後くらい素直な気持ちを伝えてみなさいよ……！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Then don't regret it later. At the very least, be honest with yourself at the end...!"
L13_1.m_Talk_ENG = L14_1
