L28_1.m_Talk_JPN = L29_1
L29_1 = "The only thing I regret... is the helpless and unknown me. You...!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "最初我唯一後悔的就是……無能的無名時期的我，也就是你！"
