L37_1 = "우리 세계는 여기서 끝나더라도, 최후의 걸작인 자네가 살아남는다면 우리의 승리라네."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "私たちの世界はここで終わっても、最後の傑作である君が生き残ったなら私たちの勝利だ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Our world might end here, but it will be our victory if you, the final masterpiece, survive."
L36_1.m_Talk_ENG = L37_1
L37_1 = "即使我們的世界在此終結，只要你這幅最後的傑作能活下來，那就是我們的勝利。"
