L38_1.m_Pos = "C"
L39_1 = "보이지 않는 실타래처럼 얽힌 세계의 법칙을 언젠가 간파해 낼 수 있을 테니까."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "目に見えない糸のように絡まっている世界の法則を、いつか見抜けるはずだからね。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Someday, you'll be able to unravel the laws of this world that are intertwined by invisible threads."
L38_1.m_Talk_ENG = L39_1
L39_1 = "你終有一天能夠洞悉，有如看不見的絲線般交織的世界法則。"
